import org.deeptimeline.app.LabelSolver
import kotlin.math.abs
fun main(){val gap=25.0;val anchors=doubleArrayOf(-800.0,-500.0)+DoubleArray(15){it.toDouble()}+doubleArrayOf(600.0,950.0);fun solved(origin:Double)=LabelSolver.solve(anchors,gap,origin)
for(origin in listOf(-1200.0,-200.0,-0.1,0.0)){val a=solved(origin);check(abs(a[2]-anchors[2])<1e-7){"First entry not straight with stack below center at $origin"}};for(origin in listOf(14.0,14.1,250.0,1400.0)){val a=solved(origin);check(abs(a[16]-anchors[16])<1e-7){"Last entry not straight with stack above center at $origin"}};for(index in 2..16){val result=solved(anchors[index]);check(abs(result[index]-anchors[index])<1e-7){"Focused anchor moved at $index"}};for(origin in listOf(-1000.0,-200.0,-12.5,0.0,3.3,6.9,14.0,180.0,1200.0)){val result=solved(origin);for(i in 1 until result.size)check(result[i]-result[i-1]>=gap-1e-7){"Overlap at $origin"};for(i in listOf(0,1,17,18))check(abs(result[i]-anchors[i])<1e-7){"Unrelated event $i bent at $origin"}};var last:DoubleArray?=null;for(step in -500..2000){val origin=step*0.01;val current=solved(origin);last?.let{old->for(i in current.indices)check(abs(current[i]-old[i])<0.5){"Abrupt motion at $origin event $i from ${old[i]} to ${current[i]}"}};last=current};for(index in 2..16){val origin=anchors[index];val left=solved(origin-0.00001);val middle=solved(origin);val right=solved(origin+0.00001);for(i in 2..16)check(abs((middle[i]-left[i])-(right[i]-middle[i]))<0.0001){"Velocity discontinuity at $origin event $i"}};val duplicated=doubleArrayOf(-500.0,0.0,0.0,0.0,0.0,100.0,600.0);val ties=LabelSolver.solve(duplicated,gap,0.0);for(i in 2..4)check(abs(ties[i]-ties[i-1]-gap)<1e-7);check(abs(ties[1]+37.5)<1e-7&&abs(ties[4]-37.5)<1e-7);for(step in -1000..1000){val origin=step*0.01;val result=LabelSolver.solve(duplicated,gap,origin);for(i in 1 until result.size)check(result[i]-result[i-1]>=gap-1e-7)};println("Hyperflow: stable stack entry/exit, center-pass continuity, isolated events, ordered rows, tied timestamps: PASS")}
